command:
C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe -NoProfile -Command '
$devs = Invoke-RestMethod -Uri "http://127.0.0.1:3080/v3/projects/CampusNetwork_02/nodes" -Method Get
$cmd = [uri]::EscapeDataString("display current-configuration")
foreach ($dev in $devs) {
  $id = [uri]::EscapeDataString($dev.node_id)
  $cur = (Invoke-RestMethod -Uri "http://127.0.0.1:3080/v3/projects/CampusNetwork_02/nodes/$id/command?cmd=$cmd" -Method Get).output
  $ref = (Invoke-RestMethod -Uri "http://127.0.0.1:3080/v3/projects/CampusNetwork-for-perf_02/nodes/$id/command?cmd=$cmd" -Method Get).output
  $curLines = @($cur -split "\r?\n" | Where-Object { $_ -notmatch "^!Last configuration" })
  $refLines = @($ref -split "\r?\n" | Where-Object { $_ -notmatch "^!Last configuration" })
  $diff = @(Compare-Object -ReferenceObject $refLines -DifferenceObject $curLines)
  if ($diff.Count -gt 0) {
    Write-Output "DEVICE:$($dev.node_id)"
    $diff | ForEach-Object { Write-Output "$($_.SideIndicator) $($_.InputObject)" }
  }
}'
